export function Text({ children, raw, ...rest }: TextProps & { raw?: boolean }) {
  const { t } = useLang();
  if (raw) return <RNText {...rest}>{children}</RNText>;
  const map = (c: React.ReactNode): React.ReactNode => (typeof c === 'string' ? t(c) : c);
  return <RNText {...rest}>{Array.isArray(children) ? children.map(map) : map(children)}</RNText>;
}

